{"code":"import std.collection.*

func processEntry(q: LinkedList<Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -1
    }
    var idx: Int64 = 0
    var found = false
    var prev: ?LinkedListNode<Int64> = None
    var cur = q.firstNode()
    while (let Some(node) <- cur) {
        if (node.value == t) {
            found = true
            break
        }
        prev = cur
        cur = node.next
        idx++
    }
    if (!found) {
        return -1
    }
    let newNode = LinkedListNode<Int64>(t + 10)
    match (prev) {
        case Some(p) =>
            newNode.prev = p
            newNode.next = p.next
            match (p.next) {
                case Some(n) => n.prev = newNode
                case None => q.addLast(t + 10)
            }
            p.next = newNode
        case None =>
            let first = q.firstNode()
            match (first) {
                case Some(f) =>
                    newNode.next = f
                    f.prev = newNode
                    q.addFirst(t + 10)
                case None => q.addLast(t + 10)
            }
    }
    return idx
}

