func processEntry(q: TreeMap<Int64,Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -61
    }
    let first = q.first()
    let (k, v) = first
    return v - k + t
}

main() {
    let c0 = TreeMap<Int64,Int64>()
    c0.add(4, 0)
    c0.add(-2, 19)
    c0.add(7, 23)
    let r0 = processEntry(c0, 1)
    let w0 = ArrayList<Int64>()
    for ((k, v) in c0) {
        w0.add(k)
        w0.add(v)
    }
    println(r0 == 22 && w0.toArray() == [-2, 19, 4, 0, 7, 23])
    let c1 = TreeMap<Int64,Int64>()
    c1.add(1, 3)
    c1.add(6, 11)
    let r1 = processEntry(c1, 2)
    let w1 = ArrayList<Int64>()
    for ((k, v) in c1) {
        w1.add(k)
        w1.add(v)
    }
    println(r1 == 4 && w1.toArray() == [1, 3, 6, 11])
}

